    {
      "chord_quality": "quartal",
      "function_role": "harmonic-family-membership",
      "narrative": "Goodrick treats quartal voicings (3-part and 4-part 4ths) as structurally opposed to tertial chord families: \"tertial harmony and quartal harmony are pretty much exact opposites.\" The primary intervals of a quartal voicing are 4ths and 5ths; 3rds and 6ths are present only as color or secondary intervals, the inverse of triads (Chapter 5, p. 9).",
      "source_principle_ids": [],
      "source_work_id": "almanac-vol-2",
      "references": [
        {
          "source": "almanac-vol-2",
          "citation": "Chapter 5 p. 9"
        }
      ],
      "provenance": "extracted",
      "granularity_level": "a",
      "granularity_name": "harmonic-family"
    },
    {
      "chord_quality": "quartal",
      "function_role": "color-tone-exclusion",
      "narrative": "Goodrick prescribes excluding 3rds and 6ths as primary intervals in a quartal voicing context: the interval inventory of a 3-part 4th chord is Two 2nds, Four 4ths, Two 5ths, One 7th \u2014 Primary intervals: 4ths and 5ths; Color intervals: 3rds and 6ths (missing) (Chapter 5, p. 10).",
      "source_principle_ids": [],
      "source_work_id": "almanac-vol-2",
      "references": [
        {
          "source": "almanac-vol-2",
