      "granularity_level": "c",
      "granularity_name": "omission-priority"
    },
    {
      "chord_quality": "quartal",
      "function_role": "enharmonic-collapse-avoidance",
      "narrative": "The diminished 4th between B and Eb is proscribed in quartal voicing context because it sounds like a major 3rd despite appearing as a 4th on the staff: they don't work very well in a 4th voicings context. A quartal voicing containing B\u2013Eb risks collapsing into a triadic sonority (Chapter 5, p. 9).",
      "source_principle_ids": [],
      "source_work_id": "almanac-vol-2",
      "references": [
        {
          "source": "almanac-vol-2",
          "citation": "Chapter 5 p. 9"
        }
      ],
      "provenance": "extracted",
      "polarity": "proscriptive",
      "granularity_level": "b",
      "granularity_name": "voicing-floor"
    },
    {
      "chord_quality": "quartal",
      "function_role": "drop-d-pedal-exploration",
      "narrative": "Goodrick prescribes tuning the low E string down a whole step to D and using it as a pedal while cycling through all 4th-voicing positions, placing the player in D Dorian where there aren't any avoid notes (Chapter 5, p. 10).",
      "source_principle_ids": [],
      "source_work_id": "almanac-vol-2",
      "references": [
        {
          "source": "almanac-vol-2",
          "citation": "Chapter 5 p. 10"
        }
