      "provenance": "extracted",
      "granularity_level": "h",
      "granularity_name": "idiom-application"
    },
    {
      "chord_quality": "quartal",
      "function_role": "melodic-generation-via-arpeggiation",
      "narrative": "Goodrick prescribes arpeggiation of quartal voicing shapes as a melodic generation tool. The five M-Lode applications (melodies, arpeggios, counterpoint, 3-part chords, 4-part chords) all apply to quartal material (Chapter 5, p. 10; Chapter 6, p. 11).",
      "source_principle_ids": [],
