    {
      "chord_quality": "quartal",
      "function_role": "voice-leading-grid-application",
      "narrative": "Goodrick prescribes analyzing every quartal voicing through a paired Intervallic/Functional Voice-Leading grid. Example for 3-part 4ths Cycle 6 Close: 5\u21922nd / 2\u21922nd / 1\u21922nd intervallic; 5\u21921 / 2\u21925 / 1\u21922 functional (Chapter 19, p. 27).",
      "source_principle_ids": [],
