      "granularity_level": "g",
      "granularity_name": "voice-leading"
    },
    {
      "chord_quality": "quartal",
      "function_role": "common-tone-preservation",
      "narrative": "When traversing quartal positions within a cycle, any voice that does not move is annotated as c.t. (common tone) \u2014 a distinct analytical category. Example: 4-part 4ths Cycle 2 (C Major, 4-way close) shows voices 4 and 1 as c.t. while voices 7 and 3 move (Chapter 19, p. 27; Chapter 23, p. 159).",
      "source_principle_ids": [],
      "source_work_id": "almanac-vol-2",
