    },
    {
      "chord_quality": "quartal",
      "function_role": "fingerstyle-application-requirement",
      "narrative": "Drop 3 and 4 is only for finger-style guitarists. The Double Drop 2/Drop 4 (octave inserted between the middle two voices of a Drop 2) also favors fingerstyle, which enables partial barres and selective string plucking (Chapter 10, p. 15; Chapter 8, p. 14).",
      "source_principle_ids": [],
