    },
    {
      "chord_quality": "quartal",
      "function_role": "spread-cluster-physical-caution",
      "narrative": "Many spread cluster voicings are difficult to play on the guitar: BE VERY CAREFUL!!! Spread clusters are extremely interesting and mostly unknown but demand careful physical preparation (Chapter 16, p. 22).",
      "source_principle_ids": [],
