    {
      "chord_quality": "quartal",
      "function_role": "harmonic-minor-scale-preference",
      "narrative": "Prefer C Harmonic Minor as the scale context for quartal and M-Lode voicing exploration: IT JUST SOUNDS BETTER IN HARMONIC MINOR (Chapter 15, p. 20).",
      "source_principle_ids": [],
